import {STRATEGIES,GRADES,TOTAL,betCount,betLabel,validateConfig,predict} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const fmt=n=>Number(n).toLocaleString('zh-CN'),money=n=>(n<0?'−':'')+'¥'+fmt(Math.abs(n)),pad=n=>String(n).padStart(2,'0');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let draws=[],result=null,worker=null,page=0,historyPage=0,historyQuery='',detailIssue=null,lastPrediction=null,running=false;
const manual={red:[],blue:[],dan:[],tuo:[]};
const HELP={hot100:'按当时之前100期的出现次数排序；相同数据和设置会得到相同结果。',blend:'70%近100期频率 + 30%近30期频率；相同设置的结果固定。',hot30:'按当时之前30期的出现次数排序；相同设置的结果固定。',cold100:'选择当时之前100期出现次数较少的号码；相同设置的结果固定。',overdue:'选择截至当时连续未出现期数最长的号码；相同设置的结果固定。',hotcold:'按此前100期出现次数排序，冷热两端交替取号；红球和蓝球分别计算。',oddeven:'红球按奇、偶交替取号，各组内部按此前100期热度排序；蓝球按近100期热度排序。',zones:'红球按1—11、12—22、23—33三区轮流取号，各区内部按此前100期热度排序；蓝球按近100期热度排序。',random:'每一期都随机生成号码；勾选“每次运行重新随机”后，重复点击会看到不同的模拟结果。',manual:'固定这组号码回看历史，属于事后分析，不能当作事前预测成绩。'};
function showError(message){$('#notice').textContent=message;$('#notice').hidden=false;}
function clearError(){$('#notice').hidden=true;}
function balls(red=[],blue=[],actual=null,large=false){return `<div class="balls">${red.map(v=>ball(v,false,actual?.red.includes(v),large)).join('')}${red.length&&blue.length?'<span class="plus">+</span>':''}${blue.map(v=>ball(v,true,actual?.blue===v,large)).join('')}</div>`;}
function ball(v,blue=false,hit=false,large=false){return `<span class="ball${blue?' blue':''}${hit?' hit':''}${large?' large':''}">${pad(v)}</span>`;}
function readConfig(){return{strategy:$('#strategy').value,type:$('#bet-type').value,redCount:Number($('#red-count').value),blueCount:Number($('#blue-count').value),danCount:Number($('#dan-count').value),tuoCount:Number($('#tuo-count').value),seed:Number($('#seed').value),freshRandom:$('#fresh-random').checked,periods:Number($('#periods').value),end:Number($('#end-issue').value),manual:structuredClone(manual)};}
function freshSeed(){const value=new Uint32Array(1);crypto.getRandomValues(value);return value[0]||1;}
function maxPeriods(){return Number($('#end-issue').value)-($('#strategy').value==='manual'?0:500);}
function updateConfig(){
 const c=readConfig(),isDan=c.type==='dan';$('#red-count').closest('div').hidden=isDan;$('#pool-fields').style.gridTemplateColumns=isDan?'1fr':'1fr 1fr';$('#dan-fields').hidden=!isDan;$('#manual-picker').hidden=c.strategy!=='manual';$('#random-fields').hidden=c.strategy!=='random';$('#seed').disabled=c.strategy==='random'&&c.freshRandom;$('#strategy-help').textContent=HELP[c.strategy];$('#periods').max=Math.max(1,maxPeriods());$('#tuo-count').min=7-c.danCount;$('#tuo-count').max=33-c.danCount;
 try{const checked=validateConfig({...c,strategy:c.strategy==='manual'?'hot100':c.strategy},draws.length||3510,true);const count=betCount(checked);$('#stake').textContent=money(count*2);$('#bet-formula').textContent=`${betLabel(checked)} · ${fmt(count)}注 × ¥2`;}
 catch{ $('#stake').textContent='—';$('#bet-formula').textContent='请检查号码个数'; }
 if(c.strategy==='manual')renderPicker();
}
function renderPicker(){
 const c=readConfig();const groups=c.type==='dan'?[['dan','红球胆码',33,c.danCount],['tuo','红球拖码',33,c.tuoCount],['blue','蓝球',16,c.blueCount]]:[['red','红球',33,c.redCount],['blue','蓝球',16,c.blueCount]];
 $('#manual-picker').innerHTML=groups.map(([key,label,max,target])=>`<div class="picker-title">${label}<span>已选 ${manual[key].length} / ${target}</span></div><div class="number-grid" role="group" aria-label="选择${label}">${Array.from({length:max},(_,i)=>{const v=i+1,selected=manual[key].includes(v),blocked=key==='tuo'?manual.dan.includes(v):key==='dan'?manual.tuo.includes(v):false;return `<button type="button" class="number-button ${key}${selected?' selected':''}" data-pick-group="${key}" data-number="${v}" aria-label="${label}${pad(v)}" aria-pressed="${selected}" ${blocked?'disabled':''}>${pad(v)}</button>`;}).join('')}</div>`).join('')+'<div class="picker-actions"><button type="button" id="clear-picks">清空号码</button><button type="button" id="fill-picks">用当前热号填入</button></div>';
}
$('#manual-picker').addEventListener('click',e=>{
 const button=e.target.closest('[data-pick-group]');if(button){const key=button.dataset.pickGroup,v=Number(button.dataset.number),a=manual[key],c=readConfig(),max=key==='red'?c.redCount:key==='blue'?c.blueCount:key==='dan'?c.danCount:c.tuoCount;if(a.includes(v))manual[key]=a.filter(x=>x!==v);else if(a.length<max)manual[key]=[...a,v].sort((a,b)=>a-b);else{showError(`最多选择${max}个号码，请先取消一个已选号码。`);return;}clearError();renderPicker();}
 if(e.target.id==='clear-picks'){Object.keys(manual).forEach(k=>manual[k]=[]);renderPicker();}
 if(e.target.id==='fill-picks'){try{const p=predict(draws,{...readConfig(),strategy:'hot100'});Object.assign(manual,structuredClone(p.pick));renderPicker();clearError();}catch(e){showError(e.message);}}
});
$('#quick-periods').addEventListener('click',e=>{const b=e.target.closest('[data-period]');if(!b)return;$('#periods').value=b.dataset.period==='all'?maxPeriods():Math.min(Number(b.dataset.period),maxPeriods());$$('#quick-periods button').forEach(x=>x.classList.toggle('selected',x===b));});
$('#periods').addEventListener('input',()=>$$('#quick-periods button').forEach(x=>x.classList.remove('selected')));
['strategy','bet-type','red-count','blue-count','dan-count','tuo-count','seed','fresh-random'].forEach(id=>$('#'+id).addEventListener('change',updateConfig));
$('#end-issue').addEventListener('change',()=>{if(Number($('#periods').value)>maxPeriods())$('#periods').value=Math.max(1,maxPeriods());updateConfig();});
function setTab(tab){$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.tab-panel').forEach(p=>p.hidden=p.id!==tab);clearError();if(tab==='prediction'&&!$('#prediction-form'))renderPredictionShell();if(tab==='history')renderHistory();}
$$('.tab').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
function run(){
 if(running)return Promise.reject(new Error('正在运行回测，请稍候。'));
 let config;try{const raw=readConfig();if(raw.strategy==='random'&&raw.freshRandom){raw.seed=freshSeed();$('#seed').value=raw.seed;}config=validateConfig(raw,draws.length);}catch(e){showError(e.message);return Promise.reject(e);}
 clearError();running=true;$('#run-button').disabled=true;$('#run-button').textContent='正在计算…';$('#result-body').classList.add('loading');$('#export-results').disabled=true;
 return new Promise((resolve,reject)=>{
  worker?.terminate();worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});
  const finish=()=>{running=false;$('#run-button').disabled=false;$('#run-button').innerHTML='<span class="play-icon" aria-hidden="true">▶</span> 运行回测';$('#result-body').classList.remove('loading');worker?.terminate();worker=null;};
  worker.onmessage=({data})=>{if(data.progress!==undefined){$('#run-button').textContent=`正在计算 ${Math.round(data.progress*100)}%`;return;}if(data.error){finish();showError(data.error);reject(new Error(data.error));return;}result=data.result;page=0;detailIssue=null;renderResults();finish();$('#export-results').disabled=false;resolve(result);};
  worker.onerror=()=>{finish();showError('回测暂时无法运行，请刷新后重试。');reject(new Error('回测计算失败'));};worker.postMessage({draws,config});
 });
}
$('#backtest-form').addEventListener('submit',e=>{e.preventDefault();run().catch(()=>{});});
$('#rerun-random').addEventListener('click',()=>{if($('#strategy').value!=='random')$('#strategy').value='random';$('#fresh-random').checked=true;updateConfig();run().catch(()=>{});});
function chart(records){
 const W=800,H=260,l=70,r=12,t=20,b=36,max=Math.max(...records.map(x=>Math.max(x.cumulativeCost,x.cumulativePrize)),1),plotW=W-l-r,plotH=H-t-b;
 const sample=records.length<=260?records:records.filter((_,i)=>i===0||i===records.length-1||i%Math.ceil(records.length/250)===0);
 const index=new Map(records.map((x,i)=>[x.issue,i]));const x=i=>l+plotW*(records.length===1?1:i/(records.length-1));const y=v=>H-b-plotH*v/max;
 const path=key=>`M${l},${H-b} `+sample.map(v=>`L${x(index.get(v.issue)).toFixed(1)},${y(v[key]).toFixed(1)}`).join(' ');
 const grid=Array.from({length:5},(_,i)=>{const v=max*i/4;return `<line x1="${l}" x2="${W-r}" y1="${y(v)}" y2="${y(v)}" stroke="#e8edf0"/><text x="${l-10}" y="${y(v)+4}" text-anchor="end">${v>=10000?(v/10000).toFixed(1)+'万':Math.round(v)}</text>`;}).join('');
 return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="累计成本${money(records.at(-1).cumulativeCost)}，累计已知奖金${money(records.at(-1).cumulativePrize)}"><defs><linearGradient id="prize-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#159085" stop-opacity=".14"/><stop offset="1" stop-color="#159085" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path('cumulativePrize')} L${W-r},${H-b} Z" fill="url(#prize-fill)"/><path d="${path('cumulativeCost')}" fill="none" stroke="#aab7c5" stroke-width="2.5" stroke-dasharray="6 5"/><path d="${path('cumulativePrize')}" fill="none" stroke="#128a80" stroke-width="2.6"/><text x="${l}" y="${H-7}">${records[0].issue}期</text><text x="${W-r}" y="${H-7}" text-anchor="end">${records.at(-1).issue}期</text></svg>`;
}
function renderResults(){
 const r=result,unknown=r.unknown>0,returnRate=r.prize/r.cost*100,best=r.counts.slice(1).findIndex(x=>x>0)+1,max=Math.max(...r.records.map(x=>x.payout));
 $('#result-title').textContent=`${STRATEGIES[r.config.strategy]} · ${betLabel(r.config)}`;$('#result-range').textContent=`${r.startIssue}—${r.endIssue}期 · ${fmt(r.periods)}期 · 每期${fmt(r.tickets)}注${r.config.strategy==='random'?` · 本次随机编号 ${r.config.seed}`:''}`;$('#rerun-random').hidden=r.config.strategy!=='random';
 $('#result-body').innerHTML=`${r.config.strategy==='random'?`<div class="notice-banner">这是第 ${r.config.seed} 号随机样本。点击“再随机一次”会重新生成每一期的模拟号码，用来观察结果波动；单次样本不代表真实长期概率。</div>`:''}${r.config.strategy==='manual'?'<div class="notice-banner">固定号码历史回看：这组号码是在现在选定的，历史命中不等于当时能提前预测。</div>':''}${unknown?'<div class="notice-banner">有浮动奖的奖金字段缺失。下方显示已知奖金下限，净额与返还比例并非完整结算。</div>':''}<div class="metrics"><article class="metric"><span>模拟总成本</span><strong>${money(r.cost)}</strong><small>每期 ${money(r.costPerPeriod)} × ${fmt(r.periods)}期</small></article><article class="metric"><span>${unknown?'已知奖金下限':'奖金合计'}</span><strong>${unknown?'≥':''}${money(r.prize)}</strong><small>含适用期间福运奖 · 税前</small></article><article class="metric ${r.net<0?'loss':'profit'}"><span>${unknown?'已知奖金减成本':'模拟净额'}</span><strong>${unknown?'≥':''}${money(r.net)}</strong><small>奖金 − 投入</small></article><article class="metric"><span>中奖期比例</span><strong>${(r.winningPeriods/r.periods*100).toFixed(1)}<em>%</em></strong><small>${fmt(r.winningPeriods)} / ${fmt(r.periods)}期有奖</small></article></div>
 <div class="card chart-card"><div class="card-heading"><div><h3>累计投入与奖金</h3><p>两条线之间，是中奖之外的成本。</p></div><div class="legend"><span><i class="cost-key"></i>投入</span><span><i class="prize-key"></i>奖金</span></div></div>${chart(r.records)}</div>
 <div class="result-bottom"><div class="card padded"><div class="card-heading"><div><h3>奖级分布</h3><p>展开后的中奖注数，同一期可中多注。</p></div></div>${r.counts.slice(1).map((v,i)=>`<div class="prize-bar"><span>${GRADES[i+1]}</span><div class="prize-track"><i style="width:${v?Math.max(2,Math.log1p(v)/Math.log1p(Math.max(...r.counts.slice(1),1))*100):0}%"></i></div><b>${fmt(v)}</b></div>`).join('')}</div><div class="card padded"><h3>不只看中奖次数</h3><ul class="summary-list"><li><span>${unknown?'已知奖金 / 投入':'奖金 / 投入'}</span><b>${unknown?'≥':''}${returnRate.toFixed(2)}%</b></li><li><span>奖金超过当期成本</span><b>${unknown?'至少':''}${fmt(r.profitablePeriods)}期</b></li><li><span>单期最高${unknown?'已知':''}奖金</span><b>${money(max)}</b></li><li><span>最高命中奖级</span><b>${best?GRADES[best]:'未中奖'}</b></li><li><span>同注数一等奖理论概率</span><b>约 ${fmt(Math.round(TOTAL/r.tickets))} 分之一</b></li></ul><p class="field-help">理论概率假设公平独立开奖。提高组合覆盖也会增加成本，历史表现不保证未来收益。</p></div></div>
 <div class="card table-card"><div class="card-heading"><div><h3>逐期明细</h3><p>展开查看当时选了什么，实际中了什么。</p></div><select id="result-filter" aria-label="筛选回测结果" style="width:auto"><option value="all">全部期数</option><option value="wins">有中奖</option><option value="profit">当期盈利</option></select></div><div id="detail-table"></div></div><p class="result-footnote">${r.config.strategy==='manual'?'手动回看使用固定号码。':'自动回测每期仅使用此前的数据；前500期作为初始历史。'} 金额按记录与规则折算，未经逐期官方核验。数据截止 ${draws.at(-1).date}。</p>`;
 $('#result-filter').addEventListener('change',()=>{page=0;detailIssue=null;renderResultTable();});renderResultTable();
}
function selectedRecords(){const filter=$('#result-filter')?.value??'all';return [...result.records].reverse().filter(r=>filter==='wins'?r.counts.slice(1).some(x=>x>0):filter==='profit'?r.payout>r.cost:true);}
function renderResultTable(){
 const rs=selectedRecords(),pages=Math.max(1,Math.ceil(rs.length/15));page=Math.min(page,pages-1);const shown=rs.slice(page*15,(page+1)*15);
 $('#detail-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>期号 / 日期</th><th>球池命中</th><th>最高奖级</th><th>当期奖金</th><th>当期净额</th><th></th></tr></thead><tbody>${shown.map(r=>{const best=r.counts.slice(1).findIndex(x=>x>0)+1;return `<tr><td><strong class="num">${r.issue}</strong><br><span class="field-help">${r.date}</span></td><td>${r.redHits}红 + ${r.blueHit}蓝${result.config.type==='dan'?`<br><span class="field-help">其中胆码 ${r.danHits}/${result.config.danCount}</span>`:''}</td><td>${best?`<span class="badge">${GRADES[best]}</span>`:'—'}</td><td class="num">${r.unknown?'≥':''}${money(r.payout)}</td><td class="num ${r.net<0?'amount-negative':'amount-positive'}">${r.unknown?'≥':''}${money(r.net)}</td><td><button class="tiny-button" data-detail="${r.issue}" aria-expanded="${detailIssue===r.issue}">${detailIssue===r.issue?'收起':'查看'}</button></td></tr>${detailIssue===r.issue?`<tr class="detail-expansion"><td colspan="6"><div class="detail-columns"><div><p>${result.config.type==='dan'?'当时所选胆码':'当时所选号码'} · 实心球表示命中</p>${balls(result.config.type==='dan'?r.pick.dan:r.pick.red,r.pick.blue,{red:r.actualRed,blue:r.actualBlue})}${result.config.type==='dan'?`<p>拖码</p>${balls(r.pick.tuo,[],{red:r.actualRed,blue:r.actualBlue})}`:''}</div><div><p>实际开奖</p>${balls(r.actualRed,[r.actualBlue])}<p>${r.counts.slice(1).map((n,i)=>n?`${GRADES[i+1]} ${fmt(n)}注`:'').filter(Boolean).join(' · ')||'该期未中奖'}</p>${r.unknown?'<p class="error-text">浮动奖奖金字段缺失，金额暂未完整计算。</p>':''}</div></div></td></tr>`:''}`;}).join('')||'<tr><td colspan="6" class="empty">没有符合条件的开奖期。</td></tr>'}</tbody></table></div><div class="pager"><span>共 ${fmt(rs.length)}期 · ${page+1} / ${pages}页</span><div class="pager-buttons"><button class="secondary" data-page="prev" ${page===0?'disabled':''}>上一页</button><button class="secondary" data-page="next" ${page>=pages-1?'disabled':''}>下一页</button></div></div>`;
}
$('#result-body').addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){detailIssue=detailIssue===detail.dataset.detail?null:detail.dataset.detail;renderResultTable();}const b=e.target.closest('[data-page]');if(b){page+=b.dataset.page==='next'?1:-1;detailIssue=null;renderResultTable();}});
function download(name,rows){const csv='\ufeff'+rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#export-results').addEventListener('click',()=>{if(!result)return;download(`双色球回测_${result.startIssue}-${result.endIssue}.csv`,[['规则',STRATEGIES[result.config.strategy],'买法',betLabel(result.config)],['期号','日期','所选红球','胆码','拖码','蓝球','实际红球','实际蓝球','投入','已知奖金','已知奖金减投入','缺失浮动奖金注数',...GRADES.slice(1)],...result.records.map(r=>[r.issue,r.date,r.pick.red.map(pad).join(' '),r.pick.dan.map(pad).join(' '),r.pick.tuo.map(pad).join(' '),r.pick.blue.map(pad).join(' '),r.actualRed.map(pad).join(' '),pad(r.actualBlue),r.cost,r.payout,r.net,r.unknown,...r.counts.slice(1)])]);});
function renderPredictionShell(){
 $('#prediction').innerHTML=`<div class="prediction-layout"><aside class="config card"><div class="section-kicker"><span>01</span> 生成下一期参考</div><h2>选择生成规则</h2><form id="prediction-form"><label for="pred-strategy">选号规则</label><select id="pred-strategy">${Object.entries(STRATEGIES).filter(([k])=>k!=='manual').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><label for="pred-type">投注方式</label><select id="pred-type"><option value="pool">单式 / 复式</option><option value="dan">红球胆拖</option></select><div class="two-col"><div id="pred-red-wrap"><label for="pred-red">红球个数</label><input id="pred-red" type="number" value="6" min="6" max="33" required></div><div><label for="pred-blue">蓝球个数</label><input id="pred-blue" type="number" value="2" min="1" max="16" required></div></div><div id="pred-dan-fields" class="two-col" hidden><div><label for="pred-dan">胆码</label><input id="pred-dan" type="number" value="4" min="1" max="5"></div><div><label for="pred-tuo">拖码</label><input id="pred-tuo" type="number" value="5" min="2" max="29"></div></div><label for="pred-seed" id="pred-seed-label" hidden>随机种子</label><input id="pred-seed" type="number" value="20260930" min="1" max="4294967295" hidden><p class="field-help">使用截至 ${draws.at(-1).issue} 期的全部可用历史。不会自动获取未来开奖。</p><button class="primary" type="submit" style="margin-top:22px">生成参考号码</button></form></aside><section><div class="notice-banner">这是规则生成的下一期参考，不是更高中奖概率的承诺。热门、冷门和遗漏不改变公平独立开奖下单注的概率。</div><div id="prediction-output"></div></section></div>`;
 $('#pred-type').addEventListener('change',()=>{const dan=$('#pred-type').value==='dan';$('#pred-dan-fields').hidden=!dan;$('#pred-red-wrap').hidden=dan;});$('#pred-strategy').addEventListener('change',()=>{const random=$('#pred-strategy').value==='random';$('#pred-seed').hidden=!random;$('#pred-seed-label').hidden=!random;});$('#prediction-form').addEventListener('submit',e=>{e.preventDefault();generatePrediction();});generatePrediction();
}
function readPredictionConfig(){return{strategy:$('#pred-strategy').value,type:$('#pred-type').value,redCount:Number($('#pred-red').value),blueCount:Number($('#pred-blue').value),danCount:Number($('#pred-dan').value),tuoCount:Number($('#pred-tuo').value),seed:Number($('#pred-seed').value)};}
function generatePrediction(){try{
 const config=readPredictionConfig();if(config.strategy==='random'){config.seed=freshSeed();$('#pred-seed').value=config.seed;}const p=predict(draws,config);lastPrediction=p;clearError();const reds=p.config.type==='dan'?[...p.pick.dan,...p.pick.tuo]:p.pick.red;
 $('#prediction-output').innerHTML=`<div class="card reference-card"><span class="label-chip">截至 ${p.lastIssue} 期 · ${p.date}</span><p class="eyebrow">NEXT DRAW / REFERENCE ONLY</p><h2>${STRATEGIES[p.config.strategy]} · ${betLabel(p.config)}</h2>${p.config.type==='dan'?`<p class="field-help" style="margin-bottom:10px">胆码</p>${balls(p.pick.dan,[],null,true)}<p class="field-help" style="margin-bottom:10px">拖码与蓝球</p>${balls(p.pick.tuo,p.pick.blue,null,true)}`:balls(p.pick.red,p.pick.blue,null,true)}<div class="reference-sub"><div>组合数<strong>${fmt(p.tickets)} <small>注</small></strong></div><div>对应成本<strong>${money(p.tickets*2)}</strong></div><div>一等奖理论概率<strong style="font-size:19px">约 ${fmt(Math.round(TOTAL/p.tickets))} 分之一</strong></div></div><p class="field-help">${HELP[p.config.strategy]} 胆拖规则取排名最前的号码作胆码，其余作拖码。</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="secondary" id="copy-prediction">复制号码</button><button class="secondary" id="backtest-pred-rule">回测这套规则</button><button class="secondary" id="backtest-pred-fixed">固定号码历史回看</button></div></div><div class="card table-card"><div class="card-heading"><div><h3>这些号码的历史表现</h3><p>统计依据，不是下一期概率评分。</p></div></div><div class="table-wrap"><table><thead><tr><th>号码</th><th>用途</th><th>近100期</th><th>近30期</th><th>当前遗漏</th></tr></thead><tbody>${[...reds.map(v=>['red',v]),...p.pick.blue.map(v=>['blue',v])].map(([color,v])=>{const s=p.stats[color][v-1];return `<tr><td>${ball(v,color==='blue')}</td><td>${color==='blue'?'蓝球':p.pick.dan.includes(v)?'胆码':p.config.type==='dan'?'拖码':'红球'}</td><td class="num">${s.last100}次</td><td class="num">${s.last30}次</td><td class="num">${s.omission}期</td></tr>`;}).join('')}</tbody></table></div></div>`;
 $('#copy-prediction').addEventListener('click',async()=>{const text=p.config.type==='dan'?`胆码：${p.pick.dan.map(pad).join(' ')}；拖码：${p.pick.tuo.map(pad).join(' ')}；蓝球：${p.pick.blue.map(pad).join(' ')}`:`红球：${p.pick.red.map(pad).join(' ')}；蓝球：${p.pick.blue.map(pad).join(' ')}`;try{await navigator.clipboard.writeText(text);$('#copy-prediction').textContent='已复制';}catch{showError('浏览器未允许复制，请直接选中号码复制。');}});
 $('#backtest-pred-rule').addEventListener('click',()=>{applyConfig({...p.config,periods:Math.min(1000,draws.length-500),end:draws.length});setTab('backtest');run().catch(()=>{});});
 $('#backtest-pred-fixed').addEventListener('click',()=>{Object.assign(manual,structuredClone(p.pick));applyConfig({...p.config,strategy:'manual',manual:p.pick,periods:1000,end:draws.length});setTab('backtest');run().catch(()=>{});});return p;
 }catch(e){showError(e.message);return null;}}
function applyConfig(c){const ids={strategy:'strategy',type:'bet-type',redCount:'red-count',blueCount:'blue-count',danCount:'dan-count',tuoCount:'tuo-count',seed:'seed',periods:'periods',end:'end-issue'};for(const [key,id]of Object.entries(ids))if(c[key]!==undefined)$('#'+id).value=c[key];if(c.manual)Object.assign(manual,structuredClone(c.manual));updateConfig();}
function renderHistory(){
 const latest=draws.at(-1);$('#history').innerHTML=`<div class="card history-latest"><div><span class="label-chip">内置数据最新一期</span><h2>${latest.issue} 期</h2><p>${latest.date} · 数据快照，非实时同步</p></div>${balls(latest.red,[latest.blue],null,true)}</div><div class="history-tools"><div><h2 style="margin:0 0 6px">历史开奖</h2><p class="history-info">共 ${fmt(draws.length)} 期 · 日期从新到旧</p></div><input id="history-search" type="search" placeholder="搜索期号或日期，如 26113" aria-label="搜索历史期号或日期" value="${escape(historyQuery)}"></div><div class="card table-card" id="history-table" style="margin-top:0"></div>`;$('#history-search').addEventListener('input',e=>{historyQuery=e.target.value;historyPage=0;renderHistoryTable();});renderHistoryTable();
}
function renderHistoryTable(){
 const rs=[...draws].reverse().filter(r=>r.issue.includes(historyQuery.trim())||r.date.includes(historyQuery.trim()));const pages=Math.max(1,Math.ceil(rs.length/20));historyPage=Math.min(historyPage,pages-1);
 $('#history-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>期号</th><th>开奖日期</th><th>开奖号码</th><th>红球和值</th><th>奇 : 偶</th></tr></thead><tbody>${rs.slice(historyPage*20,(historyPage+1)*20).map(r=>`<tr><td class="num">${r.issue}</td><td class="num">${r.date}</td><td>${balls(r.red,[r.blue])}</td><td class="num">${r.red.reduce((a,b)=>a+b,0)}</td><td class="num">${r.red.filter(v=>v%2).length} : ${r.red.filter(v=>v%2===0).length}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有找到匹配的期号或日期。</td></tr>'}</tbody></table></div><div class="pager"><span>共 ${fmt(rs.length)}期 · ${historyPage+1} / ${pages}页</span><div class="pager-buttons"><button class="secondary" id="history-prev" ${historyPage===0?'disabled':''}>上一页</button><button class="secondary" id="history-next" ${historyPage===pages-1?'disabled':''}>下一页</button></div></div>`;$('#history-prev').onclick=()=>{historyPage--;renderHistoryTable();};$('#history-next').onclick=()=>{historyPage++;renderHistoryTable();};
}
function registerTools(){
 const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tools=[{name:'read_lottery_state',description:'读取已加载数据范围、当前回测摘要与参考号码，不改变页面。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({draws:draws.length,lastIssue:draws.at(-1).issue,result:result?{strategy:result.config.strategy,periods:result.periods,cost:result.cost,knownPrize:result.prize,unknownPrizeTickets:result.unknown,winningPeriods:result.winningPeriods}:null,reference:lastPrediction?.pick??null})},
 {name:'run_lottery_backtest',description:'按给定期数与已有规则运行回测，更新页面并返回摘要。只使用开奖前数据；不是购彩操作。',inputSchema:{type:'object',properties:{periods:{type:'integer',minimum:1,maximum:3010},strategy:{type:'string',enum:['hot100','blend','hot30','cold100','overdue','hotcold','oddeven','zones','random']},redCount:{type:'integer',minimum:6,maximum:33},blueCount:{type:'integer',minimum:1,maximum:16}},required:['periods','strategy','redCount','blueCount'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input)=>{if(!input||typeof input!=='object')throw new Error('需要回测配置。');const c=validateConfig({...input,type:'pool',seed:20260930,end:draws.length},draws.length);applyConfig(c);setTab('backtest');const r=await run();return{periods:r.periods,cost:r.cost,knownPrize:r.prize,net:r.net,unknownPrizeTickets:r.unknown,winningPeriods:r.winningPeriods};}}];
 for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}
async function init(){try{const response=await fetch('./draws.json');if(!response.ok)throw new Error('历史数据加载失败，请刷新重试。');draws=await response.json();if(!Array.isArray(draws)||draws.length<501)throw new Error('历史数据格式不完整。');$('#dataset-count').innerHTML=`${fmt(draws.length)} <small>期历史数据</small>`;$('#dataset-date').textContent=`${draws[0].date.replaceAll('-','.')} — ${draws.at(-1).date.replaceAll('-','.')}`;$('#end-issue').innerHTML=draws.slice(500).map((r,i)=>`<option value="${i+501}">${r.issue} · ${r.date}</option>`).reverse().join('');updateConfig();await run();registerTools();}catch(e){showError(e.message);$('#result-body').innerHTML='<div class="card empty">数据暂未就绪，请刷新页面重试。</div>';}}
init();
